#[must_use]
pub fn api_function(name: &str) -> Option<&'static ApiFunction> {
    API_FUNCTIONS
        .binary_search_by_key(&name, |function| function.name)
        .ok()
        .map(|index| &API_FUNCTIONS[index])
}

